	h := r.WithGroup("g").WithAttrs(slog.String("k", "v"))
	log := slog.New(h)

	log.Info("msg")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g" {
			found = true
		}
		return true
	})
	if !found {
		t.Fatal("expected group attr 'g' wrapping 'k'/'v'")
	}
}

